
.status-bar {
  width: 100%;
  max-width: 720px;
  background-color: var(--c-surface);
  background-image: linear-gradient(135deg, var(--c-surface) 0%, var(--c-bg) 100%);
  border: 1px solid var(--c-accent);
  border-radius: 8px;
  font-family: var(--font-body);
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.5;
  margin: 0 auto;
  padding: 12px 16px;
  box-shadow: 0 1px 4px rgba(74, 138, 130, 0.08);
}

.world-row {
  display: flex;
  align-items: baseline;
  gap: 6px;

  .label {
    font-weight: 700;
    color: var(--c-accent-dark);
    min-width: 32px;
  }
  .world-name {
    color: var(--c-primary);
    font-weight: 700;
    font-size: 15px;
  }
  .scene {
    color: var(--c-text-muted);
    font-size: 12px;
  }
}

.divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--c-border), transparent);
  margin: 10px 0;
}

.section {
  .section-title {
    font-weight: 700;
    font-size: 12px;
    color: var(--c-accent-dark);
    margin-bottom: 6px;
    letter-spacing: 1px;
    position: relative;
    padding-left: 10px;

    &::before {
      content: '';
      position: absolute;
      left: 0;
      top: 50%;
      transform: translateY(-50%);
      width: 3px;
      height: 12px;
      background: var(--c-accent);
      border-radius: 2px;
    }
  }

  .badges-row {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-bottom: 4px;
  }

  .badge {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 10px;
    font-size: 12px;
    font-weight: 600;
    color: #fff;
  }

  .badge-safe { background: var(--c-safe); }
  .badge-warn { background: var(--c-warn); }
  .badge-danger { background: var(--c-danger); }
  .badge-info { background: var(--c-info); }
  .badge-muted {
    background: var(--c-border);
    color: var(--c-text-muted);
  }
  .badge-accent { background: var(--c-accent); }

  .kv-line {
    display: flex;
    gap: 6px;
    margin-top: 3px;

    .kv-label {
      min-width: 56px;
      color: var(--c-accent-dark);
      font-size: 12px;
    }
    .kv-value {
      color: var(--c-text);
      font-size: 12px;
    }
  }
}

.footprint-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.footprint-item {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  padding: 3px 6px;
  border-radius: 4px;
  background: rgba(184, 212, 207, 0.18);

  .fp-name {
    color: var(--c-primary);
    font-weight: 600;
  }
  .fp-fame {
    color: var(--c-accent-dark);
    font-style: italic;
  }
}
